# {{ now().strftime('%-I:%M') }}
### {{ now().strftime('%A, %B %-d') }}
Outside {{ states('sensor.thermostat_1_outdoor_temperature') | round(0) }}° · Bathroom {{ states('sensor.master_bath_temperature') | round(0) }}° · Floor {{ states('sensor.master_bath_floor_temperature') | round(0) }}°

{% set evening = states('sensor.bath_screen_mode') == 'evening' %}{% set s = 'sensor.evening_briefing' if evening else 'sensor.morning_briefing' %}{% set t = state_attr(s, 'text') %}{% set fresh = has_value(s) and (now() - as_datetime(states(s))).total_seconds() < 14 * 3600 %}
## {{ 'Good evening' if evening else 'Good morning' }}
{% if t and fresh %}{{ t }}{% else %}{{ 'Tonight’s note is written at 7:30 PM.' if evening else 'The morning briefing is written at 6:30 AM.' }}{% endif %}

{% set evening = states('sensor.bath_screen_mode') == 'evening' %}{% set ev = state_attr('sensor.bath_screen_agenda', 'events') or [] %}{% set icons = {'flight': 'mdi:airplane', 'trash': 'mdi:trash-can-outline', 'family': 'mdi:calendar-blank'} %}{% for day in (['tomorrow'] if evening else ['today', 'tomorrow']) %}
## {{ day | capitalize }}
{% for e in ev if e.day == day and (evening or day == 'today' or e.kind == 'flight' or e.time.endswith('AM')) %}<ha-icon icon="{{ icons[e.kind] }}"></ha-icon> **{{ e.time }}** · {{ e.summary }}<br>{% else %}Nothing on the calendar.{% endfor %}
{% endfor %}

